// A1 Config + fontes grátis (sem chave). Cada item = 1 fonte; o nó HTTP seguinte busca uma por vez.
const COMPANY_ID = '4a617a32-8493-4bd1-a9ab-12f5edf2055a'; // CYTRON
const DRY_RUN = true; // true = só mostra; false = grava em mkt_content_ideas (nó Supabase precisa estar ativo)
const enc = encodeURIComponent;
const NEWS_QUERIES = ['"small business" AI automation', 'AI receptionist tradies', 'Gold Coast small business', 'AI agents customer service'];
const SUBREDDITS = ['smallbusiness', 'Entrepreneur', 'automation', 'n8n', 'AusFinance'];
const HN_QUERIES = ['AI automation small business', 'AI agents'];
// Canais do YouTube via RSS público (channel_id). Ajustar a lista na quinta.
const YT_CHANNELS = { 'Nate Herk (n8n)': 'UC2ojq-nuP8ceeHqiroeKhBA', 'Liam Ottley': 'UCui4jxDaMb53Gdh-AZUTPAg' };
const out = [];
out.push({ source: 'google_trends', label: 'Google Trends AU (diário)', url: 'https://trends.google.com/trending/rss?geo=AU', parser: 'trends_rss' });
for (const q of NEWS_QUERIES) out.push({ source: 'google_news', label: 'Google News: ' + q, url: `https://news.google.com/rss/search?q=${enc(q + ' when:7d')}&hl=en-AU&gl=AU&ceid=AU:en`, parser: 'rss' });
for (const s of SUBREDDITS) out.push({ source: 'reddit', label: 'r/' + s, url: `https://www.reddit.com/r/${s}/top/.rss?t=week&limit=15`, parser: 'atom' });
for (const q of HN_QUERIES) out.push({ source: 'hacker_news', label: 'HN: ' + q, url: `https://hn.algolia.com/api/v1/search?query=${enc(q)}&tags=story&numericFilters=${enc('created_at_i>' + Math.floor(Date.now()/1000 - 7*86400))}&hitsPerPage=15`, parser: 'hn' });
for (const [name, id] of Object.entries(YT_CHANNELS)) out.push({ source: 'youtube', label: 'YouTube: ' + name, url: `https://www.youtube.com/feeds/videos.xml?channel_id=${id}`, parser: 'atom' });
return out.map(j => ({ json: { ...j, company_id: COMPANY_ID, dry_run: DRY_RUN, run_at: new Date().toISOString() } }));

// A3 Normaliza, pontua e deduplica. Sem rede. Saída = linhas prontas para mkt_content_ideas.
const srcs = $('Sources (free, no key)').all().map(i => i.json);
const resp = $input.all().map(i => i.json);
const dec = s => String(s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const tag = (x, t) => { const m = x.match(new RegExp(`<${t}[^>]*>([\\s\\S]*?)</${t}>`, 'i')); return m ? dec(m[1]) : ''; };
const blocks = (x, t) => x.match(new RegExp(`<${t}[\\s>][\\s\\S]*?</${t}>`, 'gi')) || [];
const KW = { 'ai': 3, 'automation': 4, 'automate': 4, 'agent': 3, 'agents': 3, 'chatbot': 3, 'small business': 5, 'smb': 3, 'tradie': 5, 'tradies': 5, 'plumber': 3, 'electrician': 3, 'gold coast': 6, 'brisbane': 4, 'queensland': 3, 'australia': 2, 'lead': 2, 'leads': 3, 'booking': 3, 'receptionist': 4, 'missed call': 5, 'customer service': 3, 'n8n': 4, 'workflow': 2, 'crm': 3, 'marketing': 2, 'invoice': 2, 'quote': 2, 'productivity': 1, 'hiring': 1, 'cost': 1 };
const NEG = ['crypto', 'nsfw', 'giveaway', 'promo code', 'politic', 'election', 'murder', 'football', 'cricket', 'afl'];
const hash = s => { let h = 5381; for (const c of s) h = ((h << 5) + h + c.charCodeAt(0)) | 0; return (h >>> 0).toString(36); };
const norm = s => s.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const rows = []; const errors = [];
resp.forEach((r, i) => {
  const s = srcs[i] || {}; const body = typeof r.data === 'string' ? r.data : (r.data ? JSON.stringify(r.data) : '');
  if (r.error || !body) { errors.push({ source: s.label, error: String(r.error?.message || r.error || 'empty') }); return; }
  let items = [];
  try {
    if (s.parser === 'hn') items = (JSON.parse(body).hits || []).map(h => ({ title: h.title, url: h.url || `https://news.ycombinator.com/item?id=${h.objectID}`, published: h.created_at, engagement: (h.points || 0) + 2 * (h.num_comments || 0) }));
    else if (s.parser === 'atom') items = blocks(body, 'entry').map(e => ({ title: tag(e, 'title'), url: (e.match(/<link[^>]*href="([^"]+)"/) || [])[1], published: tag(e, 'published') || tag(e, 'updated'), summary: (tag(e, 'content') || tag(e, 'media:description')).slice(0, 400) }));
    else items = blocks(body, 'item').map(e => ({ title: tag(e, 'title'), url: tag(e, 'link'), published: tag(e, 'pubDate'), summary: tag(e, 'description').slice(0, 400), traffic: tag(e, 'ht:approx_traffic') }));
  } catch (e) { errors.push({ source: s.label, error: 'parse: ' + e.message }); return; }
  for (const it of items) {
    if (!it.title) continue;
    const text = norm(it.title + ' ' + (it.summary || ''));
    if (NEG.some(n => text.includes(n))) continue;
    const hits = Object.keys(KW).filter(k => (' ' + text + ' ').includes(' ' + k + ' '));
    let score = hits.reduce((a, k) => a + KW[k], 0) * 3;
    const ageH = it.published ? (Date.now() - new Date(it.published).getTime()) / 36e5 : 96;
    score += Math.max(0, 20 - ageH / 8);                       // recência (até +20)
    if (it.engagement) score += Math.min(25, Math.log10(1 + it.engagement) * 10);
    if (it.traffic) score += Math.min(15, (parseInt(String(it.traffic).replace(/\D/g, '')) || 0) / 20000);
    if (s.source === 'google_trends' && !hits.length) score = Math.min(score, 15); // trend genérica = baixa prioridade
    rows.push({ company_id: s.company_id, source: s.source, source_url: it.url || null, title: it.title.slice(0, 500), summary: it.summary || null,
      keywords: hits, language: 'en', region: 'AU', score: Math.round(Math.min(100, score) * 100) / 100, status: 'new',
      dedupe_key: s.source + ':' + hash(norm(it.title)), raw: { feed: s.label, published: it.published || null, engagement: it.engagement || null, traffic: it.traffic || null } });
  }
});
const seen = new Set(); const uniq = rows.filter(r => !seen.has(r.dedupe_key) && seen.add(r.dedupe_key)).sort((a, b) => b.score - a.score);
const MIN = 25, TOP = 40;
const keep = uniq.filter(r => r.score >= MIN).slice(0, TOP);
return [{ json: { dry_run: srcs[0]?.dry_run !== false, total_raw: rows.length, total_unique: uniq.length, kept: keep.length, errors, ideas: keep, preview: keep.slice(0, 10).map(r => `${r.score} | ${r.source} | ${r.title}`) } }];
